import json,sys,re,math
from pathlib import Path
p=Path(sys.argv[1]);d=json.loads((p/'thread-cpu.json').read_text());samples=d['samples'];first={x['tid']:x for x in samples[0]['threads']};last={x['tid']:x for x in samples[-1]['threads']};assert first.keys()==last.keys();assert all({x['tid'] for x in s['threads']}==first.keys() for s in samples)
rows=[]
for tid,a in first.items():
 b=last[tid];assert a['start_ticks']==b['start_ticks'];rows.append({'tid':tid,'name':b['name'],'start_ticks':b['start_ticks'],'user_ms':(b['user_ticks']-a['user_ticks'])*1000/d['clock_ticks_per_second'],'system_ms':(b['system_ticks']-a['system_ticks'])*1000/d['clock_ticks_per_second']})
r={'diagnostic_only':True,'samples':len(samples),'elapsed_seconds':(samples[-1]['monotonic_ns']-samples[0]['monotonic_ns'])/1e9,'thread_tick_ms':1000/d['clock_ticks_per_second'],'threads':rows,'total_sampled_gui_thread_cpu_ms':sum(r['user_ms']+r['system_ms'] for r in rows),'debugger':json.loads((p/'thread-gdb.json').read_text()),'limits':['Repeated /proc reads and one stop-the-process GDBsnapshot perturb the measured workload; not qualification or unbiased stack profiling.','Same thread IDs/start ticks observed throughout; snapshots cannot exclude threads born and exited entirely between samples. Tick deltas have10ms resolution per counter.','One stack in poll_console_lifetime/SystemTime::now does not establish that function as a hot spot.','Main-thread CPU includes application/backend/driver calls and logging; thread attribution is not exclusive subsystem attribution.']}
(p/'thread-analysis.json').write_text(json.dumps(r,indent=2)+'\n');print('CPUms',r['total_sampled_gui_thread_cpu_ms'],'mainshare',sum(x['user_ms']+x['system_ms'] for x in rows if x['tid']==d['pid'])/r['total_sampled_gui_thread_cpu_ms'],'debugger',r['debugger'])
